import utils
from copy import deepcopy


def tally(ballots, candidates):
    tallies = {i:0 for i in candidates}
    for b in ballots:
        tallies[b.prefs[0]] += b.votes
    return tallies


def step(ballots, candidates, quota, candidate, action, test=False):
    tallies = {i:0 for i in candidates}
    tallies_cards = {i:0 for i in candidates}
    tallies_transferable = {i:0 for i in candidates}
    ballotsnew = []
    price = 0
    if action == 0:  # elim
        for b in ballots:
            tallies[b.prefs[0]] += b.votes
            prefs = deepcopy(b.prefs)
            if candidate in prefs:
                prefs.remove(candidate)
            if not prefs:
                continue
            x = utils.Ballot(b.num, b.votes, prefs, b.atl)
            x.papers = b.papers
            ballotsnew += [x]
        if min(tallies.values()) < tallies[candidate]:
            price += tallies[candidate] - min(tallies.values())
        elif tallies[candidate] >= quota:
            price += tallies[candidate] - quota
    else:  # seat
        for b in ballots:
            tallies[b.prefs[0]] += b.votes
            tallies_cards[b.prefs[0]] += b.papers
            if len(b.prefs) > 1:
                tallies_transferable[b.prefs[0]] += b.votes
            #     if b.prefs[0] == candidate:
            #         print("->", b.num, b.votes, b.prefs, b.atl, b.papers)
            # else:
            #     if b.prefs[0] == candidate:
            #         print("XX", b.num, b.votes, b.prefs, b.atl, b.papers)
        if tallies[candidate] < quota:
            price += max(quota, max(tallies.values())) - tallies[candidate]
            tval = 0  # nothing is transfered, all ballots used fully
        else:
            # if test:
            tval = min(1, (tallies[candidate]-quota)/tallies[candidate])
            # else:
            #     tval = min(1, (tallies[candidate]-quota)/tallies_transferable[candidate])
            # tval = min(1, (tallies[candidate]-quota)/tallies_cards[candidate])
            print(tallies[candidate], quota, tallies[candidate]-quota, tallies_cards[candidate], tval)
        for b in ballots:
            prefs = deepcopy(b.prefs)
            if candidate in prefs:
                prefs.remove(candidate)
            if not prefs:
                continue
            if candidate == b.prefs[0]:
                x = utils.Ballot(b.num, b.votes * tval, prefs, b.atl)
                x.papers = b.papers
                ballotsnew += [x]
            else:
                x = utils.Ballot(b.num, b.votes, prefs, b.atl)
                x.papers = b.papers
                ballotsnew += [x]
    print(tallies)
    candidates.remove(candidate)
    return ballotsnew, price


candidates, ballots, a, b, c = utils.read_ballots_blt("../stv-rla/data/Scotland/2022/preferenceprofile_v0004_ward-4-oban-south-and-the-isles_06052022_143143.blt")
order_c = []
order_a = []
order_q = {}
winners = []
quota, tallies, totvotes = utils.simulate_stv(ballots, candidates, 4, order_c, order_a, order_q, winners, log=None)
candidates = list(range(len(candidates)))
#quota = 727
totprice = 0
ballotsnew, price = step(ballots, candidates, quota, 7, 1, test=True)
totprice += price
print("7s", price)
ballotsnew, price = step(ballotsnew, candidates, quota, 10, 0)
totprice += price
print("7s 10e", price)
ballotsnew, price = step(ballotsnew, candidates, quota, 0, 0)
totprice += price
print("7s 10e 0e", price)
ballotsnew, price = step(ballotsnew, candidates, quota, 8, 0)
totprice += price
print("7s 10e 0e 8e", price)
ballotsnew, price = step(ballotsnew, candidates, quota, 2, 0)
totprice += price
print("7s 10e 0e 8e 2e", price)
ballotsnew, price = step(ballotsnew, candidates, quota, 1, 0)
totprice += price
print("7s 10e 0e 8e 2e 1e", price)
ballotsnew, price = step(ballotsnew, candidates, quota, 6, 0)
